@app.route('/profile')
def profile():
    # --------------------------------------------
    username = request.args.get('name', session.get('username', 'Guest'))

    # --------------------------------------------
    comment = request.args.get('comment', 'No comment')

    # --------------------------------------------
    template_str = '''
        <h1>User Profile</h1>
        <p>Welcome, {{ username }}!</p>
        <p>Your comment: {{ comment }}</p>
        {% if username == 'admin' %}
        <p style="color:red;">Password Hint: {{ admin_password }}</p>
        {% endif %}
    '''

    from flask import render_template_string
    return render_template_string(
        template_str, 
        username=username, 
        comment=comment, 
        admin_password=ADMIN_PASSWORD if username == 'admin' else None
    )
